  "landing.combo.feature.reminders.title": "Reminders that run themselves",
  "landing.combo.feature.reminders.sub":
    "Overdue loans, service due dates, and backordered claims remind both sides on their own — and every update lands in your inbox.",
  "landing.combo.feature.truck.title": "Truck accounts",
  "landing.combo.feature.truck.sub": "Balances, payments, and credit limits in plain view for both sides.",
  "landing.combo.feature.paid.title": "Get paid through the site",
  "landing.combo.feature.paid.sub":
    "Customers can pay their truck balance online, so agents get paid directly — no chasing checks.",
  "landing.combo.feature.flyers.title": "Weekly flyer showcase",
  "landing.combo.feature.flyers.sub":
    "Dealer agents post their weekly flyers where every customer can see them.",
  "landing.combo.feature.findAgent.title": "Find a local dealer or agent",
  "landing.combo.feature.findAgent.sub":
    "Search by ZIP and distance, and keep your preferred agents a tap away.",
  "landing.combo.feature.crew.title": "One account for the whole crew",
  "landing.combo.feature.crew.sub":
    "Shops can pay for an account that gives their employees access to the system.",
  "landing.combo.feature.sharing.title": "Sharing you control",
  "landing.combo.feature.sharing.sub":
    "Share exactly the tool lists you choose, read-only — and take them back any time.",
  "landing.combo.feature.reports.title": "Reports in one click",
  "landing.combo.feature.reports.sub": "Inventory, value, tax, and claim reports as PDF, CSV, or Excel.",
  "landing.combo.feature.reportsSaved.title": "Reports you build & save",
  "landing.combo.feature.reportsSaved.sub":
    "Build a report with your own columns, save it as a template, and pull it again any time.",
  "landing.combo.feature.backups.title": "Backed up daily",
  "landing.combo.feature.backups.sub": "Automatic daily backups with restore points.",
  "landing.combo.feature.history.title": "History & restore points",
  "landing.combo.feature.history.sub":
    "Every change to your records is journaled — roll the vault back to a restore point and bring deleted records back.",
  "landing.combo.feature.drive.title": "A copy in your own Drive",
  "landing.combo.feature.drive.sub":
    "Connect your own Google Drive and your vault backs itself up there on your schedule — daily, weekly, or monthly.",
  "landing.combo.feature.onboarding.title": "Full onboarding wizard",
  "landing.combo.feature.onboarding.sub":
    "A guided setup that walks every new account through its types, modules, and sharing — step by step.",
  "landing.combo.feature.walkthroughs.title": "\"Do it with me\" walkthroughs",
  "landing.combo.feature.walkthroughs.sub":
    "First time lending a tool out or filing a repair claim? A guided pass walks you through the real thing, step by step.",
  "landing.combo.feature.widgets.title": "Dashboard widgets you arrange",
  "landing.combo.feature.widgets.sub":
    "Your home page starts with your key stats — then you add, arrange, and fine-tune ready-made widgets for every part of your shop, or build your own from exactly the pieces you want to see.",
  "landing.combo.feature.insuranceAccess.title": "Policy-ready inventory access",
  "landing.combo.feature.insuranceAccess.sub":
    "Insurance agents can request access to a client's inventory list, so the policy is written on what's really in the box.",
  "landing.combo.feature.forum.title": "The community forum",
  "landing.combo.feature.forum.sub":
    "Mechanics talking shop — and if anything is out of line, flag it and the moderators step in.",
  "landing.combo.feature.marketplace.title": "Tools for sale classifieds",
  "landing.combo.feature.marketplace.sub":
    "Buy and sell tools with other members, or post what you're hunting for.",
  "landing.combo.feature.parts.title": "Parts for sale board",
  "landing.combo.feature.parts.sub": "The community parts board — find the part without the runaround.",
  "landing.combo.feature.expansion.title": "Expansion suggestions",
  "landing.combo.feature.expansion.sub": "The site spots the add-ons that complete the sets you already own.",
  "landing.combo.feature.videos.title": "How-to videos",
  "landing.combo.feature.videos.sub": "Short walkthroughs that show you, not tell you.",
  "landing.combo.feature.support.title": "Real support from real people",
  "landing.combo.feature.support.sub": "Open a ticket and talk with the support team.",
  "landing.combo.feature.boards.title": "Bug & feature boards",
  "landing.combo.feature.boards.sub": "Report a bug, ask for a feature, and vote on what gets built.",
  "landing.combo.feature.importSheet.title": "Bring your list with you",
  "landing.combo.feature.importSheet.sub":
    "Import your existing spreadsheet — the free sheet drops straight into the vault.",
  "landing.combo.feature.contacts.title": "Contact cards, in and out",
  "landing.combo.feature.contacts.sub":
    "Export your borrowers and agents as contact cards; import a card to add someone back.",
  "landing.combo.feature.language.title": "English y español",
  "landing.combo.feature.language.sub": "The whole site works in English or Spanish — switch any time.",
  "landing.combo.feature.theme.title": "Your theme, your colors",
  "landing.combo.feature.theme.sub": "Light or dark theme and your own accent color, everywhere on the site.",
  "landing.combo.feature.currency.title": "Your own currency",
  "landing.combo.feature.currency.sub":
    "Your account runs in your currency — and prices from other members show a converted hint in yours.",
  "landing.combo.feature.refer.title": "Refer and earn",
  "landing.combo.feature.refer.sub": "Every 5 paying members you refer earns you a free month of Pro.",
  "landing.combo.feature.exportData.title": "Take your data with you",
  "landing.combo.feature.exportData.sub": "Export everything, any time. Your records are yours, not ours.",
  "landing.combo.feature.downloads.title": "Free downloads for the shop",
  "landing.combo.feature.downloads.sub":
    "Forms, spreadsheets, and charts — a paycheck calculator, inspection forms, diagnostic worksheets — free to everyone, no email needed.",
  "landing.combo.feature.converter.title": "Converters & an Ohm's-law calculator",
  "landing.combo.feature.converter.sub":
    "Pressure, volume, torque, and temperature conversions right on the downloads page — type a reading, get the rest. Pin the converter to your Home dashboard and it's always one tap away.",
  "landing.combo.feature.prints3d.title": "Free 3D print files from members",
  "landing.combo.feature.prints3d.sub":
    "Shop prints shared by the community — socket rails, drawer organizers, mounts and jigs. Free to download, with versions, ratings, and the STEP files behind them.",
  "landing.combo.feature.visitorPreview.title": "See your pages the way visitors do",
  "landing.combo.feature.visitorPreview.sub":
    "One tap on your own print listings and dealer pages shows exactly what other members see — their view, not your owner controls — so nothing about your listing surprises you.",
  "landing.combo.feature.wallpapers.title": "Free HD wallpaper for the shop",
  "landing.combo.feature.wallpapers.sub":
    "Mechanics, tool trucks, and Toolbox Vault artwork in high definition — sized for desktop, tablet, and phone, free to everyone.",
