    "File the claim, add the items it covers, then work the claim's to-do list: the documents and photos your insurer wants, gathered on the claim's own page. Deadlines like proof of loss stay in view until they're met, and the claim moves from filed, to in review, to approved and paid.",
  "disasterClaims.how.valueTitle": "Valued at what you paid",
