  "settings.history.title": "History & restore",
  "settings.history.intro":
    "Everything you add, change or delete is recorded here. If something goes wrong — a tool deleted by accident, a whole list wiped — pick a restore point and your account rolls back to exactly how it was then. Records shared with other people (borrowing, tool-list shares, filed claims) are listed for completeness but never rewound: restoring your account doesn't rewrite anyone else's. Deleted files are kept for a while so restores bring your photos back too.",
