  "settings.modules.title": "Modules",
  "settings.modules.intro":
    "Choose which parts of Toolbox Vault show up in your account. Turning a module off hides it everywhere — menus, your home page, search and notifications — but never deletes anything. Turn it back on anytime and it returns exactly as it was. Changes save as you make them — there is no save button.",
