  "toolExpansion.title": "Tool Expansion",
  "toolExpansion.subtitle":
    "Addons other owners have for the same tools and sets you own — matched by model number. Move the ones you don't want to your archived matches, and report a match that doesn't belong.",
  "toolExpansion.loading": "Loading…",
  "toolExpansion.loadFailed": "Couldn't load your expansions.",
